entries[187051] = { ["name"] = "Forgotten Feather", ["text"] = "Binds when picked up\nToy\nUse: Give your battle pet the power of the Val'kyr, allowing them to fly alongside you. (10 Sec Cooldown)" }
entries[187052] = { ["name"] = "The Netherstar", ["text"] = "Korthian Relics\nBinds when picked up\nUnique\nThis Item Begins a Quest\n\"Thrumming gently with potential energy.\"" }
entries[187054] = { ["name"] = "Lost Razorwing Egg", ["text"] = "Binds when picked up\n\"The devourer must have either raided a razorwing nest or it tumbled down from above. Maybe if you return it to its nest the matriarch will be grateful.\"" }
entries[187055] = { ["name"] = "Pouch of Rune Chits", ["text"] = "Korthian Relics\nBinds when picked up\nThis Item Begins a Quest\n\"A single lonely chit rattles around in the pouch.\"" }
entries[187056] = { ["name"] = "The Devouring Cold", ["text"] = "Binds when picked up\nOne-Hand Sword\n55 - 92 Damage Speed 2.60\n(28.3 damage per second)\n+25 Strength\n+37 Stamina\n+ 35 Critical Strike\n+ 14 Versatility\nDurability 110 / 110\nSell Price:" }
entries[187057] = { ["name"] = "Shard of Bek", ["text"] = "Shard of Domination\nBinds when picked up\nUnique-Equipped: Blood Shard of Bek (1)\nWhile in the Maw, your damage is increased by ( 6046 / 100)% when you have 50% or more health than your target.\nSell Price:" }
entries[187059] = { ["name"] = "Shard of Jas", ["text"] = "Shard of Domination\nBinds when picked up\nUnique-Equipped: Blood Shard of Jas (1)\nWhile in the Maw, incoming healing you receive is increased by ( 302 / 10)%. Your maximum health is increased by 44844 .\nSell Price:" }
entries[187061] = { ["name"] = "Shard of Rev", ["text"] = "Shard of Domination\nBinds when picked up\nUnique-Equipped: Blood Shard of Rev (1)\nWhile in the Maw, your Leech is increased by 1209 .\nSell Price:" }
entries[187063] = { ["name"] = "Shard of Cor", ["text"] = "Shard of Domination\nBinds when picked up\nUnique-Equipped: Frost Shard of Cor (1)\nWhile in the Maw, your damage is increased by ( 6046 / 100)% for 20 sec after attacking an enemy you have not yet damaged.\nSell Price:" }
entries[187065] = { ["name"] = "Shard of Kyr", ["text"] = "Shard of Domination\nBinds when picked up\nUnique-Equipped: Frost Shard of Kyr (1)\nWhile in the Maw, gain ( 98657 * (1 + Versatility)) Absorb every 5 sec, up to a cap of 493286 .\nSell Price:" }
entries[187071] = { ["name"] = "Shard of Tel", ["text"] = "Shard of Domination\nBinds when picked up\nUnique-Equipped: Frost Shard of Tel (1)\nWhile in the Maw, your critical hits cause a nearby ally to absorb the next ( 25561 * (1 + Versatility)) damage dealt to them within 6 sec.\nSell Price:" }
entries[187073] = { ["name"] = "Shard of Dyz", ["text"] = "Shard of Domination\nBinds when picked up\nUnique-Equipped: Unholy Shard of Dyz (1)\nWhile in the Maw, damaging a target increases your damage done to that target by ( 1008 / 100)% for 4 sec, stacking up to 3 times.\nSell Price:" }
entries[187075] = { ["name"] = "Box of Rattling Chains", ["text"] = "Binds when picked up\nToy\nUse: Unleash the Minigrue, who will destroy some nearby toys. (30 Min Cooldown)" }
entries[187076] = { ["name"] = "Shard of Oth", ["text"] = "Shard of Domination\nBinds when picked up\nUnique-Equipped: Unholy Shard of Oth (1)\nWhile in the Maw, your Speed is increased by 1209\n.\nSell Price:" }
entries[187077] = { ["name"] = "Packaged Soul Ash", ["text"] = "Binds to Warband\nUse: Open to gain 250 Soul Ash.\nRequires that you have unlocked the 9th layer of Torghast.\n\"Packed for easy transfer. A significant chunk of Soul Ash was lost due to its volatile nature.\"" }
entries[187079] = { ["name"] = "Shard of Zed", ["text"] = "Shard of Domination\nBinds when picked up\nUnique-Equipped: Unholy Shard of Zed (1)\nWhile in the Maw, your helpful spells and abilities have a chance to grant your target an Unholy Aura, draining 24814 health from nearby enemies every 2 sec for 10 sec.\nSell Price:" }
