entries[187103] = { ["name"] = "Everliving Statuette", ["text"] = "Korthian Relics\nBinds when picked up\nUnique\nThis Item Begins a Quest\n\"The events that this statuette have witnessed would boggle the mind. One could learn a lot from it, if only it wasn't so duplicitous.\"" }
entries[187104] = { ["name"] = "Obelisk of Dark Tidings", ["text"] = "Korthian Relics\nBinds when picked up\nUnique\nThis Item Begins a Quest\n\"While in proximity of the obelisk, a voice in your head murmurs sweet lies and maddening truths.\"" }
entries[187105] = { ["name"] = "Memory of the Agonizing Gaze", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nAgony Gaze Runecarving Power Instant\nSinful Brand deals 10% increased damage and [ Havoc : Eye Beam /\n\nVengeance\nFel Devastation ] damage increases the duration of Sinful Brand by 0.75 sec.\nRunecarve on: Head, Legs\nSource: Granted at Renown 48 with your covenant.\nRequires: Demon Hunter" }
entries[187106] = { ["name"] = "Memory of Divine Resonance", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDivine Resonance Runecarving Power 30 yd range\nInstant\nAfter casting Divine Toll, you instantly cast [ Protection : Avenger's Shield ] [ Holy : Holy Shock /\n\nRetribution\nJudgement ] every 5 sec. This effect lasts 15 sec. (3s cooldown)\nRunecarve on: Chest, Waist\nSource: Granted at Renown 48 with your covenant.\nRequires: Paladin" }
entries[187107] = { ["name"] = "Memory of the Duty-Bound Gavel", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDuty-Bound Gavel Runecarving Power Instant\nRetribution\nVanquisher's Hammer gains 1 additional charge. An additional cast of Templar's Verdict will automatically trigger Divine Storm.\n\nHoly\nVanquisher's Hammer gains 1 additional charge. An additional cast of Word of Glory will automatically trigger Light of Dawn.\n\nProtection\nVanquisher's Hammer gains 1 additional charge. An additional cast of Word of Glory will automatically trigger Shield of the Righteous.\nRunecarve on: Head, Shoulder, Finger\nSource: Granted at Renown 48 with your covenant.\nRequires: Paladin" }
entries[187109] = { ["name"] = "Memory of a Blazing Slaughter", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nBlazing Slaughter Runecarving Power Instant\nThe Hunt engulfs you with Immolation Aura upon reaching your target and you gain 4% Agility for 12 sec for each enemy hit.\nRunecarve on: Shoulder, Feet, Back\nSource: Granted at Renown 48 with your covenant.\nRequires: Demon Hunter" }
entries[187111] = { ["name"] = "Memory of Blind Faith", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nBlind Faith Runecarving Power Instant\nElysian Decree shatters 2 additional Lesser Soul Fragments and grants you Blind Faith for 20 sec. For each Lesser Soul Fragment you consume while Blind Faith is active you gain 10 Fury and 1% Versatility, up to 20%.\nRunecarve on: Chest, Back\nSource: Granted at Renown 48 with your covenant.\nRequires: Demon Hunter" }
entries[187113] = { ["name"] = "Personal Ball and Chain", ["text"] = "Binds when picked up\nToy\nUse: Create your own Personal Ball and Chain to drag around. (5 Min Cooldown)\n\"There are many like it, but this one is mine.\"\nSell Price:" }
entries[187115] = { ["name"] = "Mawsworn Missive", ["text"] = "Quest Item\n\"Details of the Jailer's orders.\"" }
entries[187116] = { ["name"] = "Target Dummy", ["text"] = "Use: Permanently attaches a tiny device to your belt, allowing you to create a Cardboard Assassin that enemies will attack. (5 Min Cooldown)\nSell Price:" }
entries[187117] = { ["name"] = "Azure Pages", ["text"] = "Quest Item\n\"Torn pages that brim with energy.\"" }
entries[187118] = { ["name"] = "Memory of the Demonic Oath", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDemonic Oath Runecarving Power Instant\nWhen Fodder to the Flame's demon explodes it inflicts Fiery Brand to 5 nearby enemies for 5 sec. Additionally Shattered Soul's duration is increased by 8 sec.\nRunecarve on: Waist, Wrist\nSource: Granted at Renown 48 with your covenant.\nRequires: Demon Hunter" }
entries[187119] = { ["name"] = "Ring of Self-Reflection", ["text"] = "Korthian Relics\nBinds when picked up\nUnique\nThis Item Begins a Quest\n\"When the gemstone set into the band is viewed at an oblique angle, a shimmering duplicate of the ring can be seen.\"" }
entries[187120] = { ["name"] = "Blood Healing Shard 1 - Rank 5", ["text"] = "Shard of Domination\nBinds when picked up\nWhile in the Maw, your Leech is increased by 1209 ." }
entries[187123] = { ["name"] = "Empowerment Bauble", ["text"] = "Binds when picked up\n\"Use to power up target Shard of Domination\"" }
entries[187124] = { ["name"] = "Medallion of Wrath", ["text"] = "Quest Item\n\"Bestowed upon Venthyr by The Sire himself. Allows the wearer to exert partial dominion over Revendreth.\"" }
entries[187126] = { ["name"] = "Discarded Journal", ["text"] = "Quest Item\n\"Penned by the broker Xevveth, this appears to have been misplaced.\"" }
entries[187127] = { ["name"] = "Memory of Radiant Embers", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nRadiant Embers Runecarving Power Instant\nAshen Hallow's duration is increased by 50%. Cancelling your Ashen Hallow early will reduce its cooldown by up to 50%, proportional to its remaining duration.\nRunecarve on: Wrist, Hands, Back\nSource: Granted at Renown 48 with your covenant.\nRequires: Paladin" }
entries[187128] = { ["name"] = "Find-A-Spy", ["text"] = "Quest Item\nUse: Call on help from the spy catching cat, Fiona. (6 Sec Cooldown)" }
entries[187131] = { ["name"] = "Automa Internals", ["text"] = "Quest Item\n\"... goopy?\"" }
entries[187132] = { ["name"] = "Memory of the Seasons of Plenty", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSeasons of Plenty Runecarving Power Instant\nCasting Blessing of Summer grants Equinox after 10 sec.\n\nEquinox: The effectiveness of Blessing of Summer is increased by 100% for 10 sec.\nRunecarve on: Legs, Feet\nSource: Granted at Renown 48 with your covenant.\nRequires: Paladin" }
entries[187133] = { ["name"] = "Bewitching Little Hat", ["text"] = "Ember Court\nBinds when picked up\nUnique\n\"Gift to your Dredger Butler to give him the option of wearing a witch's hat.\"" }
entries[187134] = { ["name"] = "Alloy-Warping Facetor", ["text"] = "Binds when picked up\nUnique\nUse: Add a socket to a Shadowlands Season 2 item that does not already have one. Can be used on Helms, Necks, Bracers, Belts, or Rings." }
entries[187136] = { ["name"] = "Research Report: Relic Examination Techniques", ["text"] = "Binds to Warband\nUnique\nUse: You gain 50% more reputation with the Archivists' Codex when you turn in relics to the Archivist.\nRequires Tier 6 research level with The Archivists' Codex.\n\"As research techniques improve the Archivist is able to gather more knowledge from each fragment brought to him.\"" }
entries[187137] = { ["name"] = "Research Report: Relic Finding Techniques", ["text"] = "Binds when picked up\nUnique\nUse: Grants you a 20% chance to find more relic fragments when looting rares and treasures in Korthia.\n\"Knowing how to identify missing relics is critical to our efforts and so this report outlines tips and tricks to sometimes find more relic fragments from common sources.\"" }
entries[187138] = { ["name"] = "Research Report: First Alloys", ["text"] = "Binds when picked up\nUnique\nUse: Allows you to upgrade your items from Korthia and the Maw to Rank 6.\nRequires Tier 6 research level with The Archivists' Codex and Renown 75 or higher.\n\"With access to the full Archivists' Codex, we now understand the binding power of domination magic and how that lines up with some of the first alloys seen in the Shadowlands, allowing us to further improve your Korthia and Maw items.\"" }
entries[187139] = { ["name"] = "Bottled Shade Heart", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Break the seal of the bottle allowing the shade within to possess you for a short time. (1 Hour Cooldown)\n\"The contents within are best left undisturbed.\"" }
entries[187140] = { ["name"] = "Ring of Duplicity", ["text"] = "Binds when picked up\nToy\nUse: Use some of the remnant magic in the ring to summon a mirror image which copies your actions. (1 Hour Cooldown)" }
entries[187141] = { ["name"] = "Pristine Lupine Core", ["text"] = "Quest Item" }
entries[187142] = { ["name"] = "Pristine Cervid Core", ["text"] = "Quest Item" }
entries[187143] = { ["name"] = "Pristine Raptora Core", ["text"] = "Quest Item" }
entries[187145] = { ["name"] = "Treatise: Recognizing Stygia and its Uses", ["text"] = "Binds when picked up\nUnique\nUse: Permanently grants you the ability to find 10 extra Stygia when completing Daily Quests, looting treasures, or killing rare creatures that reward Stygia in the Maw or Korthia.\nRequires Tier 2 research level with The Archivists' Codex." }
entries[187148] = { ["name"] = "Death-Bound Shard", ["text"] = "Binds when picked up\nUse: Discover an upgrade to a random Conduit from among your lowest item level Conduits for your current specialization, up to item level 252.\nRequires Tier 6 research level with The Archivists' Codex.\n\"Can be used at the Forge of Bonds to uncover an unknown conduit or conduit rank.\"" }
entries[187150] = { ["name"] = "Gorak Claw Fetish", ["text"] = "Korthian Relics\nBinds when picked up\nUnique\nThis Item Begins a Quest\n\"Terrible to behold and foul-smelling besides.\"" }
entries[187152] = { ["name"] = "Automa Key", ["text"] = "Binds when picked up\nUnique" }
entries[187153] = { ["name"] = "Tasty Mawshroom", ["text"] = "Binds when picked up\nUse: Dangle a Tasty Mawshroom to attract a hungry shardhide.\n\"Only a hardy animal would find these tasty...\"" }
entries[187154] = { ["name"] = "Ancient Korthian Runes", ["text"] = "Binds when picked up\nToy\nUse: Cast the runes to reveal fate. (20 Sec Cooldown)" }
entries[187155] = { ["name"] = "Guise of the Changeling", ["text"] = "Binds when picked up\nToy\nUse: Take on the appearance of an attendant of Korthia. (30 Min Cooldown)\nSell Price:" }
entries[187158] = { ["name"] = "Deobfuscating Oculus", ["text"] = "Quest Item\nUnique\n\"Enchanted by Al'firim to pierce broker illusions.\"" }
entries[187159] = { ["name"] = "Shadow Slicing Shortsword", ["text"] = "Binds when picked up\nToy\nUse: Sever the shadow of a target player. (5 Min Cooldown)" }
entries[187160] = { ["name"] = "Memory of Pallid Command", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nPallid Command Runecarving Power\n[ Discipline : Casting Unholy Nova summons a Brooding Cleric that gains 2% additional damage and healing each time an enemy affected by Unholy Transfusion is damaged by an ally, up to 100%.\n\nThe Brooding Cleric serves you for 20 sec, healing an ally for (40% of Spell Power). ] [ Shadow : Casting Unholy Nova summons a Rattling Mage that gains 2% additional damage and healing each time an enemy affected by Unholy Transfusion is damaged by an ally, up to 100%.\n\nThe Rattling Mage serves you for 20 sec, blasting your target for (25.1% of Spell Power) Shadow damage. /\n\nHoly\nCasting Unholy Nova summons a Brooding Cleric that gains 2% additional damage and healing each time an enemy affected by Unholy Transfusion is damaged by an ally, up to 100%.\n\nThe Brooding Cleric serves you for 20 sec, healing an ally for (40% of Spell Power). ]\nRunecarve on: Feet, Finger\nSource: Granted at Renown 48 with your covenant.\nRequires: Priest" }
entries[187161] = { ["name"] = "Memory of Bwonsamdi's Pact", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nBwonsamdi's Pact Runecarving Power Instant\nEnter a pact with the Death Loa, calling forth a haunted mask that lingers on a target until Fae Guardians ends.\n\nHaunted Mask: Copies the benefit of the current faerie on its target. Follows your Direct Mask.\nRunecarve on: Head, Waist, Hands\nSource: Granted at Renown 48 with your covenant.\nRequires: Priest" }
entries[187162] = { ["name"] = "Memory of Shadow Word: Manipulation", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nShadow Word: Manipulation Runecarving Power Instant\nMindgames lasts an additional 3 sec and reverses an additional 10% damage or healing. When Mindgames can no longer reverse healing or damage, gain 5% Critical Strike for each second remaining for 10 sec.\nRunecarve on: Neck, Wrist\nSource: Granted at Renown 48 with your covenant.\nRequires: Priest" }
entries[187163] = { ["name"] = "Memory of the Spheres' Harmony", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSpheres' Harmony Runecarving Power Instant\nBoon of the Ascended's cooldown is reduced by 3 seconds, up to 60 sec, for each stack of Boon of the Ascended consumed by Ascended Eruption.\nRunecarve on: Shoulder, Legs\nSource: Granted at Renown 48 with your covenant.\nRequires: Priest" }
entries[187171] = { ["name"] = "Organic Melon", ["text"] = "Binds when picked up\nUnique\nUse: Throw a piece of fruit. (1 Min Cooldown)\n\"Will it Blend?\"" }
entries[187173] = { ["name"] = "Wriggling Tentacle", ["text"] = "Binds when picked up\nUnique\nUse: Throw a wriggling tentacle. (1 Min Cooldown)\n\"Will it Blend?\"" }
entries[187174] = { ["name"] = "Shaded Judgment Stone", ["text"] = "Binds when picked up\nToy\nUse: Judge the soul of the targeted party member. Only usable on the recently deceased. (15 Min Cooldown)" }
entries[187175] = { ["name"] = "Runekeeper's Ingot", ["text"] = "Anima\nBinds when picked up\nUse: Infuse 250 stored Anima into your covenant's Reservoir.\nSell Price:" }
entries[187176] = { ["name"] = "Vesper of Harmony", ["text"] = "Binds when picked up\nToy\nUse: Place a vesper of harmony in front of you. (30 Min Cooldown)" }
entries[187177] = { ["name"] = "Researching Korthian Relics", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"This book has some details regarding relics from Korthia and the research around them.\"\nSell Price:" }
entries[187178] = { ["name"] = "Sc'ootie's Favorite Plushie", ["text"] = "Binds when picked up\nUnique\nUse: Throw an adorable plushie. (1 Min Cooldown)\n\"Will it Blend?\"" }
entries[187179] = { ["name"] = "Glow Sticks", ["text"] = "Binds when picked up\nUnique\nUse: Throw a glow stick. (1 Min Cooldown)\n\"Will it Blend?\"" }
entries[187180] = { ["name"] = "Pitted Diaphanous Wing", ["text"] = "Sell Price:" }
entries[187181] = { ["name"] = "Small Corpsefly Egg", ["text"] = "Binds when picked up\nDuration: 3 days (real time)\n\"The Lord of the Heap's progeny should go far.\"" }
entries[187182] = { ["name"] = "Hatching Corpsefly Egg", ["text"] = "Binds when picked up\n\"See what will emerge from the egg.\"\n<Right Click to Open>" }
entries[187183] = { ["name"] = "Rampaging Mauler", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"One would think controlling a rampaging mount would be difficult, but if you can learn to control the direction of the rampage it can be quite useful.\"\nDrop:\nKonthrogz the Obliterator\nZone:\nKorthia" }
entries[187184] = { ["name"] = "Vesper of Clarity", ["text"] = "Binds when picked up\nToy\nUse: Place a vesper of clarity in front of you. (30 Min Cooldown)" }
entries[187185] = { ["name"] = "Vesper of Faith", ["text"] = "Binds when picked up\nToy\nUse: Place a vesper of faith in front of you. (30 Min Cooldown)" }
entries[187186] = { ["name"] = "Orb of Deception", ["text"] = "Binds when picked up\nUse: Copy an enemy's appearance: fooling them and their allies. While disguised: your next attack inflicts 500% increased damage.\n\"Suspicious...\"" }
entries[187187] = { ["name"] = "Korthian Armaments", ["text"] = "Binds to Warband\nUse: Create a soulbound Korthian item appropriate for your loot specialization.\nRequires Friendly reputation with the Death's Advance." }
entries[187188] = { ["name"] = "D'roo's Bottomless Gulper", ["text"] = "\"Despite your best efforts, you can't seem to fill it.\"\nSell Price:" }
entries[187189] = { ["name"] = "Hyperlight Multitool", ["text"] = "\"Invented by Di'lks of Cartel Xy, an essential tool used anywhere Broker technology is crafted.\"\nSell Price:" }
entries[187190] = { ["name"] = "Floral Print Button Down", ["text"] = "\"A vintage yet stylish garment designed by N'uth of Cartel Al.\"\nSell Price:" }
entries[187191] = { ["name"] = "Vi'ller's Preserved Eye", ["text"] = "\"It seems to lead you along the path should you find yourself lost.\"\nSell Price:" }
entries[187192] = { ["name"] = "Urn of Knowledge", ["text"] = "\"The preserved memories of Ny'lad of Cartel Ta, carefully redacted into the urn for future study before he moved on.\"\nSell Price:" }
entries[187193] = { ["name"] = "Autographed Stuffed Seagull", ["text"] = "\"The craftsmanship is stunning, an embroidered signature across the beak reads K'en.\"\nSell Price:" }
entries[187194] = { ["name"] = "Star in a Jar", ["text"] = "\"Plucked from the skies by Startamer Ja'z of Cartel Zo, the star appears carefully placed into a jar for others to enjoy.\"\nSell Price:" }
entries[187195] = { ["name"] = "Golden Sax", ["text"] = "\"An instrument once played by the legendary Myza's Oasis act, Ta'ylor.\"\nSell Price:" }
entries[187196] = { ["name"] = "Endless Arcade Token", ["text"] = "\"Ta'piper fastened an invisible string to the token, allowing endless hours of fun for he and his friends.\"\nSell Price:" }
entries[187197] = { ["name"] = "D'roo's Haunted Drumset", ["text"] = "\"A charismatic spirit appears to haunt the kit, coming to life when it hears a nearby joke.\"\nSell Price:" }
entries[187198] = { ["name"] = "Xy'le Date", ["text"] = "\"A common snack of the Xy cartel, easy to enjoy with others.\"\nSell Price:" }
entries[187199] = { ["name"] = "Pa'hix's Runepuzzle", ["text"] = "\"An intricate game to be solved with friends, created by the famous codebreaker herself.\"\nSell Price:" }
entries[187200] = { ["name"] = "Singing Steel Ingot", ["text"] = "Korthian Relics\nQuest Item\nThis Item Begins a Quest\n\"Indignant, insulted, and otherwise irritated at being pounded on by the mawsworn's steelshapers.\"" }
entries[187201] = { ["name"] = "Celestial Shadowlands Chart", ["text"] = "Korthian Relics\nQuest Item\nThis Item Begins a Quest\n\"Hovering above the scroll, a swirling multi-dimensional representation of the relative positions of various Shadowlands afterlives.\"" }
entries[187202] = { ["name"] = "Unstable Explosive Orb", ["text"] = "Korthian Relics\nQuest Item\nThis Item Begins a Quest\n\"Glowing and humming, this device clearly still carries the potential for catastrophic destruction.\"" }
entries[187203] = { ["name"] = "Cipher of Understanding", ["text"] = "Korthian Relics\nQuest Item\nThis Item Begins a Quest\n\"Several blocks of text are etched into the stone, in various languages. None of these languages are recognizable.\"" }
entries[187204] = { ["name"] = "Drum of the Death Loa", ["text"] = "Korthian Relics\nQuest Item\nThis Item Begins a Quest\n\"The drum skin, drawn taut across the frame, is unusually cool to the touch.\"" }
entries[187205] = { ["name"] = "Sack of Strange Soil", ["text"] = "Korthian Relics\nQuest Item\nThis Item Begins a Quest\n\"The dirt in this sack is a deep, rich brown... almost black.\"" }
entries[187206] = { ["name"] = "Book of Binding: The Mad Witch", ["text"] = "Korthian Relics\nQuest Item\nUnique\nThis Item Begins a Quest\n\"This book is incomplete. A deranged voice from within repeatedly and urgently requests the recovery of crimson pages.\"" }
entries[187207] = { ["name"] = "Enigmatic Decrypting Device", ["text"] = "Korthian Relics\nQuest Item\nUnique\nThis Item Begins a Quest\n\"A similar design to Broker ethertype technology, yet infinitely more complex.\"" }
entries[187208] = { ["name"] = "Shadow Slicing Shortsword", ["text"] = "Korthian Relics\nQuest Item\nUnique\nThis Item Begins a Quest\n\"Keen and bright enough to sever shadows.\"" }
entries[187209] = { ["name"] = "Lang Family Wood-Carving", ["text"] = "Korthian Relics\nQuest Item\nUnique\nThis Item Begins a Quest\n\"Well-worn with deep grooves in the wood. It must be thousands of years old.\"" }
entries[187210] = { ["name"] = "Book of Binding: The Tormented Sorcerer", ["text"] = "Korthian Relics\nQuest Item\nUnique\nThis Item Begins a Quest\n\"This book is incomplete. A deranged voice from within repeatedly and urgently requests the recovery of azure pages.\"" }
entries[187211] = { ["name"] = "Chronicle of Cartel Al", ["text"] = "\"A collection of the inscribed tales of the greatest heroes passed down through the ages, signed by Al'len.\"\nSell Price:" }
entries[187212] = { ["name"] = "Hyperlight Moccasins", ["text"] = "\"Designed with style and function in mind by the greatest shoemaker in Tazavesh, By'ron.\"\nSell Price:" }
entries[187213] = { ["name"] = "Jo's Intergalactic Cache", ["text"] = "\"Well-suited for travel, the glowing vessel contains everything you need to thrive in any corner of the galaxy.\"\nSell Price:" }
entries[187216] = { ["name"] = "Soultwining Crescent", ["text"] = "Binds when picked up\nUse: Discover an upgrade to a random Conduit from among your lowest item level Conduits for your current specialization, up to item level 226.\n\"Can be used at the Forge of Bonds to uncover an unknown conduit or conduit rank.\"\nSell Price:" }
entries[187217] = { ["name"] = "Memory of the Bountiful Brew", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nBountiful Brew Runecarving Power Instant\nApproximately 1.5 procs per minute\nYour abilities have a low chance to cast Bonedust Brew at your target's location. (500ms cooldown)\nRunecarve on: Neck, Shoulder, Chest\nSource: Granted at Renown 48 with your covenant.\nRequires: Monk" }
entries[187218] = { ["name"] = "Tome of Origins", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Vestige of Origins, a powerful Optional Reagent that increases the item level of a legendary base item.\nRequires Honored reputation with the Death's Advance." }
entries[187219] = { ["name"] = "Attendant's Token of Merit", ["text"] = "Shadowlands Season 3\nBinds when picked up\nUnique (12)\nSell Price:" }
entries[187220] = { ["name"] = "Coalesced Power", ["text"] = "Binds when picked up\nOn Pickup: Grants the Anima Power, \"Calculated Assault\".\n\"A strange orb radiating with Broker magic.\"" }
entries[187221] = { ["name"] = "Soul Ash Cache", ["text"] = "Binds when picked up\n\"Contains 250 Soul Ash.\"\n<Right Click to Open>" }
entries[187222] = { ["name"] = "Stygic Singularity", ["text"] = "Binds when picked up\n\"Contains 500 Stygia.\"\n<Right Click to Open>" }
entries[187223] = { ["name"] = "Memory of the Seeds of Rampant Growth", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSeeds of Rampant Growth Runecarving Power Instant\nEach pulse of Fae Transfusion's damage effect reduces the cooldown of Feral Spirit by 9.0 sec and increases your critical strike chance by 4% for 15 sec.\nRunecarve on: Head, Hands\nSource: Granted at Renown 48 with your covenant.\nRequires: Rogue" }
entries[187224] = { ["name"] = "Memory of the Elemental Conduit", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nElemental Conduit Runecarving Power Instant\nUp to 5 friendly targets healed by Chain Harvest will have Riptide cast on them. Up to 5 enemy targets damaged by Chain Harvest will have Flame Shock cast on them. Flame Shock critical strikes reduce the cooldown of Chain Harvest by 1.0 sec.\nRunecarve on: Chest, Wrist\nSource: Granted at Renown 48 with your covenant." }
entries[187225] = { ["name"] = "Memory of the Languishing Soul Detritus", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nLanguishing Soul Detritus Runecarving Power Instant\nWhen Scouring Tithe generates Soul Shards, gain 100% increased movement speed and 45% increased critical strike chance for 8 sec. If Scouring Tithe expires, gain 33% increased movement speed and 15% increased critical strike chance instead.\nRunecarve on: Chest, Wrist, Back\nSource: Granted at Renown 48 with your covenant.\nRequires: Warlock" }
entries[187226] = { ["name"] = "Memory of the Shards of Annihilation", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nShard of Annihilation Runecarving Power Instant\nDecimating Bolt also increases the critical strike chance by 100% and critical strike damage by 50% for [ Destruction : Incinerate / Drain Soul ] [ Demonology : Demonbolt /\n\nAffliction\nShadow Bolt ]\nRunecarve on: Waist, Legs\nSource: Granted at Renown 48 with your covenant.\nRequires: Warlock" }
entries[187227] = { ["name"] = "Memory of the Decaying Soul Satchel", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nDecaying Soul Satchel Runecarving Power Instant\nEach target affected by Soul Rot increases your haste and critical strike chance by 5% for 8 sec.\nRunecarve on: Feet, Hands\nSource: Granted at Renown 48 with your covenant.\nRequires: Warlock" }
entries[187228] = { ["name"] = "Memory of the Contained Perpetual Explosion", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nContained Perpetual Explosion Runecarving Power Instant\nImpending Catastrophe's damage over time is increased by 125% plus 15% for each enemy target hit on the way to its final target, to a maximum of 275%.\nRunecarve on: Head, Neck, Shoulder\nSource: Granted at Renown 48 with your covenant.\nRequires: Warlock" }
entries[187229] = { ["name"] = "Memory of the Pact of the Soulstalkers", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nPact of the Soulstalkers Runecarving Power Instant\nWhen your Resonating Arrow deals damage to a target, your party gains 10% increased critical strike chance for 10 sec. (1s cooldown)\nRunecarve on: Waist, Hands\nSource: Granted at Renown 48 with your covenant.\nRequires: Hunter" }
entries[187230] = { ["name"] = "Memory of the Bag of Munitions", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nBag of Munitions Runecarving Power Instant\nUp to 2 targets hit by your Death Chakram are also hit by Explosive Shot.\nRunecarve on: Head, Wrist\nSource: Granted at Renown 48 with your covenant.\nRequires: Hunter" }
entries[187231] = { ["name"] = "Memory of the Fragments of the Elder Antlers", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFragments of the Elder Antlers Runecarving Power Instant\nWhen Wild Spirits hits fewer than 5 targets, there is a 100% chance to cause Wild Spirits damage a second time.\nRunecarve on: Neck, Chest\nSource: Granted at Renown 48 with your covenant.\nRequires: Hunter" }
entries[187232] = { ["name"] = "Memory of the Pouch of Razor Fragments", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nPouch of Razor Fragments Runecarving Power\nBonus Kill Shots from Flayed Shot cause 6 targets within 12 yds to bleed for 60% of the damage dealt by Kill Shot over 6 sec.\nRunecarve on: Legs, Feet\nSource: Granted at Renown 48 with your covenant.\nRequires: Hunter" }
entries[187234] = { ["name"] = "Coalesced Power", ["text"] = "Binds when picked up\nOn Pickup: Grants the Anima Power, \"Refractive Shield\".\n\"A strange orb radiating with Broker magic.\"" }
entries[187236] = { ["name"] = "Zovaal's Dark Carafe", ["text"] = "Binds when picked up\nUse: Drink. (30 Sec Cooldown)\n\"Will you drink it or will it drink you?\"\nSell Price:" }
entries[187237] = { ["name"] = "Memory of a Call to Arms", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nCall to Arms Runecarving Power Instant\nWeapons of Order calls forth [ Brewmaster : Niuzao, the Black Ox ] [ Mistweaver : Chi-Ji, the Red Crane ] [ Windwalker : Xuen, the White Tiger / Yu'lon, the Jade Serpent ] to assist you for 12 sec. (500ms cooldown)\nRunecarve on: Legs, Feet\nSource: Granted at Renown 48 with your covenant.\nRequires: Monk" }
entries[187238] = { ["name"] = "Heavy Spiked Hide", ["text"] = "Quest Item\n\"A tough patch of hide, layered with vicious spines.\"" }
entries[187239] = { ["name"] = "Mature Ossified Beak", ["text"] = "Quest Item\n\"Boney and sharp, this beak can snap through armor.\"" }
entries[187240] = { ["name"] = "Field Warden's Watchful Eye", ["text"] = "Cosmetic\nBinds to Warband\nUnique\nBack\n1 Armor\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[187241] = { ["name"] = "Watchful Eye of the Damned", ["text"] = "Cosmetic\nBinds to Warband\nUnique\nBack\n1 Armor\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[187242] = { ["name"] = "Exterminator's Crest of the Damned", ["text"] = "Cosmetic\nBinds to Warband\nUnique\nBack\n1 Armor\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[187243] = { ["name"] = "Shadehunter's Crescent", ["text"] = "Cosmetic\nBinds to Warband\nUnique\nBack\n1 Armor\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[187244] = { ["name"] = "Questionable Mawshrooms", ["text"] = "Binds when picked up\nUse: Eat at your own risk! (30 Sec Cooldown)\n\"There are many questions to be asked about this strange growth.\"\nSell Price:" }
entries[187245] = { ["name"] = "Death-Enveloped Spires", ["text"] = "Cosmetic\nBinds to Warband\nUnique\nShoulder Cosmetic\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[187246] = { ["name"] = "Death-Enveloped Pauldrons", ["text"] = "Cosmetic\nBinds to Warband\nUnique\nShoulder Cosmetic\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[187247] = { ["name"] = "Death-Enveloped Shoulder Spikes", ["text"] = "Cosmetic\nBinds when equipped\nUnique\nShoulder Cosmetic\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[187248] = { ["name"] = "Kroke's Gleaming Spaulders", ["text"] = "Cosmetic\nBinds when equipped\nUnique\nShoulder Cosmetic\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[187250] = { ["name"] = "Kroke's Wingspiked Pauldrons", ["text"] = "Cosmetic\nBinds to Warband\nUnique\nShoulder Cosmetic\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[187251] = { ["name"] = "Shaded Skull Shoulderguards", ["text"] = "Cosmetic\nBinds to Warband\nUnique\nShoulder Cosmetic\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[187252] = { ["name"] = "Ritualist's Spiked Mantle", ["text"] = "Cosmetic\nBinds when equipped\nUnique\nShoulder Cosmetic\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[187253] = { ["name"] = "Maw Guard's Spiked Spaulders", ["text"] = "Cosmetic\nBinds when equipped\nUnique\nShoulder Cosmetic\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[187254] = { ["name"] = "Arrangement of Anima", ["text"] = "Binds when picked up\n\"Contains 175 Anima.\"\n<Right Click to Open>" }
entries[187255] = { ["name"] = "Hands of Defiance: A Chronicle of Woe", ["text"] = "Binds when picked up\n\"Recounting the tale of a clan of wicked giants damned to the Maw, and the punishments they endured for defying the Jailer.\"\n<Right Click to Read>" }
entries[187256] = { ["name"] = "Hips' Spare Fedora", ["text"] = "Ember Court\nBinds when picked up\nUnique\n\"Gift to your Dredger Butler to give him the option of wearing this cool fedora.\"\nSell Price:" }
entries[187258] = { ["name"] = "Memory of the Faeline Harmony", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nFaeline Harmony Runecarving Power Instant\nYour abilities reset Faeline Stomp 100% more often. Enemies and allies hit by Faeline Stomp are affected by Fae Exposure, increasing your damage and healing against them by 8% for 10 sec.\nRunecarve on: Waist, Hands\nSource: Granted at Renown 48 with your covenant.\nRequires: Monk" }
entries[187259] = { ["name"] = "Memory of the Raging Vesper Vortex", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nRaging Vesper Vortex Runecarving Power Instant\nWhen 3 charges of Vesper Totem are consumed, Vesper Totem will radiate a 15 yd burst of (300% of Spell Power) Arcane damage and (110% of Spell Power) healing.\nRunecarve on: Legs, Feet\nSource: Granted at Renown 48 with your covenant." }
entries[187264] = { ["name"] = "Ve'rayn's Head", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"What other secrets might it contain?\"" }
entries[187274] = { ["name"] = "Ancient Alloy", ["text"] = "Quest Item\n\"This chunk of metal is tinged with impossibly ancient magic.\"" }
entries[187275] = { ["name"] = "Helsworn Battle Plans", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Intelligence reports and battle strategies for assaulting Keeper's Respite.\"" }
entries[187276] = { ["name"] = "Stolen Korthian Supplies", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Supplies stolen from Keeper's Respite by invasive Rift monsters.\"" }
entries[187277] = { ["name"] = "Memory of Sinister Teachings", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nSinister Teachings Runecarving Power Instant\nFallen Order summons 1 additional [Ox][Crane][Tiger] adept for 24 sec. While your mystic portal is open your abilities that critically hit reduce the cooldown of Fallen Order by [ Mistweaver : 2.5 /\n\nBrewmaster, Windwalker\n5 ] sec. (750ms cooldown)\nRunecarve on: Wrist, Finger\nSource: Granted at Renown 48 with your covenant.\nRequires: Monk" }
entries[187278] = { ["name"] = "Talon-Pierced Mawsworn Lockbox", ["text"] = "Binds when picked up\n\"Falling from the wilderling's talon as you land a couple of items fall out but more items rattle within.\"\n<Right Click to Open>" }
entries[187280] = { ["name"] = "Memory of the Fae Heart", ["text"] = "Binds when picked up\nUnique\nUse: Restore the following memory to the Runecarver:\n\nHeart of the Fae Runecarving Power Instant\nShifting Power can be channeled while moving. Each enemy hit by Shifting Power grants you 1% Critical Strike and Haste, up to 10% for 15 sec.\nRunecarve on: Chest, Hands\nSource: Granted at Renown 48 with your covenant.\nRequires: Mage" }
entries[187281] = { ["name"] = "Wilderling Saddle", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"The escaped wilderling slipped this off during your last ride, insisting that you take it.\"" }
entries[187282] = { ["name"] = "Intact Aquilon Core", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Left uncrushed by the devourer, this core could power your very own aquilon.\"" }
entries[187283] = { ["name"] = "Gravewing Crystal", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Pulsing with energy, the Stonewright would be able to use this in the creation of a mount.\"" }
entries[187284] = { ["name"] = "Ominous Shard of Bek", ["text"] = "Shard of Domination\nBinds when picked up\nUnique-Equipped: Blood Shard of Bek (1)\nWhile in the Maw, your damage is increased by ( 7577 / 100)% when you have 50% or more health than your target.\nSell Price:" }
entries[187285] = { ["name"] = "Ominous Shard of Jas", ["text"] = "Shard of Domination\nBinds when picked up\nUnique-Equipped: Blood Shard of Jas (1)\nWhile in the Maw, incoming healing you receive is increased by ( 378 / 10)%. Your maximum health is increased by 56055 .\nSell Price:" }
