entries[187327] = { ["name"] = "Encrypted Korthian Journal", ["text"] = "Korthian Relics\nBinds when picked up\nUse: Submit your findings to Archivist Roh-Suir to generate 48 Cataloged Research.\n\"Written in an ancient script the journal contains a lot of notes.\"\nSell Price:" }
entries[187328] = { ["name"] = "Ripped Cosmology Chart", ["text"] = "Korthian Relics\nBinds when picked up\nUse: Submit your findings to Archivist Roh-Suir to generate 100 Cataloged Research.\n\"You can discern it is referencing the cosmos, but it is very different from any you have seen on Azeroth.\"" }
entries[187329] = { ["name"] = "Old God Specimen Jar", ["text"] = "Korthian Relics\nBinds when picked up\nUse: Submit your findings to Archivist Roh-Suir to generate 150 Cataloged Research.\n\"Floating in a suspension of some uknown liquid the eye looks perfectly preserved.\"\nSell Price:" }
entries[187330] = { ["name"] = "Naaru Shard Fragment", ["text"] = "Korthian Relics\nBinds when picked up\nUse: Submit your findings to Archivist Roh-Suir to generate 150 Cataloged Research.\n\"The fragment has a faint glow to it but you cannot tell if that is the light or more.\"\nSell Price:" }
entries[187331] = { ["name"] = "Tattered Fae Designs", ["text"] = "Korthian Relics\nBinds when picked up\nUse: Submit your findings to Archivist Roh-Suir to generate 150 Cataloged Research.\n\"This torn parchment has some familiar fae pictures on it.\"\nSell Price:" }
entries[187332] = { ["name"] = "Recovered Page of Voices", ["text"] = "Korthian Relics\nBinds when picked up\nUse: Submit your findings to Archivist Roh-Suir to generate 100 Cataloged Research.\n\"The remnants of this page has the names of attendants who have previously served the Arbiter.\"\nSell Price:" }
