entries[187595] = { ["name"] = "Favor of the Val'sharah Hippogryph", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Val'sharah Hippogryph. This is a flying mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These majestic hippogryphs are as close to a being of the Emerald Dream as any resident of Azeroth can be, and do not bond with a rider easily.\"\nVendor:\nAridormi\nZone:\nDalaran\nCost:\n5000" }
entries[187596] = { ["name"] = "Broken Isles Meat Delivery", ["text"] = "Binds when picked up\n\"A shipment of meat from Dalaran. Nomi sends his greetings.\"\n<Right Click to Open>" }
entries[187597] = { ["name"] = "Broken Isles Fish Delivery", ["text"] = "Binds when picked up\n\"A shipment of fish from Dalaran, sent with Marcia Chase's blessings.\"\n<Right Click to Open>" }
entries[187598] = { ["name"] = "Broken Isles Cloth Delivery", ["text"] = "Binds when picked up\n\"A shipment of cloth from Dalaran, thanks to Tanithria.\"\n<Right Click to Open>" }
entries[187599] = { ["name"] = "Broken Isles Herb Delivery", ["text"] = "Binds when picked up\n\"A shipment of tenderly harvested herbs from Kuhuine Tenderstride in Dalaran.\"\n<Right Click to Open>" }
entries[187600] = { ["name"] = "Broken Isles Ore Delivery", ["text"] = "Binds when picked up\n\"A shipment of ore packed specially by Mama Diggs.\"\n<Right Click to Open>" }
entries[187601] = { ["name"] = "Broken Isles Leather Delivery", ["text"] = "Binds when picked up\n\"A shipment of skins and scales selected by Kondal Huntsworn of Dalaran.\"\n<Right Click to Open>" }
entries[187602] = { ["name"] = "Firim's Motivator", ["text"] = "Quest Item\nUnique\nUse: Charge towards any confused Automa within 12 yards and give them a firm smack, causing them to obey you. (3 Sec Cooldown)\n\"A mysterious device that influences Automa's actions.\"" }
entries[187603] = { ["name"] = "The Mad Duke's Tea", ["text"] = "Binds when picked up\nUnique\nUse: Consume The Mad Duke's Tea, increasing your Primary Stat, Haste, Critical Strike chance, or Versatility for 4 hrs.\n\nYou can only have the effect of one of The Mad Duke's Tea active at a time. (1 Hour Cooldown)" }
entries[187604] = { ["name"] = "Broken Isles Enchantment Delivery", ["text"] = "Binds when picked up\n\"A shipment of enchanting supplies from Dalaran's very own enchanting supplier Ildine Sorrowspear.\"\n<Right Click to Open>" }
entries[187605] = { ["name"] = "Broken Isles Gem Delivery", ["text"] = "Binds when picked up\n\"A shipment of gems from Dalaran, courtesy of Tiffany Cartier.\"\n<Right Click to Open>" }
entries[187610] = { ["name"] = "Court of Farondis Insignia", ["text"] = "Binds to Warband\nUse: Grants 250 reputation with the Court of Farondis. (2 Sec Cooldown)" }
entries[187611] = { ["name"] = "Whispering Felflame Crystal", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest" }
entries[187612] = { ["name"] = "Key of Flowing Waters", ["text"] = "Binds when picked up\nUnique\nUse: Opens a relic chest in Korthia.\nRequires Tier 2 research level with The Archivists' Codex.\n\"The bow of this key is worn beyond recognition, weathered in the treacherous waters once present in the Estuary of Awakening.\"\nSell Price:" }
entries[187613] = { ["name"] = "Key of the Inner Chambers", ["text"] = "Binds when picked up\nUnique\nUse: Opens a relic chest in Korthia.\nRequires Tier 2 research level with The Archivists' Codex.\n\"The insignia atop the head of this key suggests it belongs to something near the great vaults.\"\nSell Price:" }
entries[187614] = { ["name"] = "Key of Many Thoughts", ["text"] = "Binds when picked up\nUnique\nUse: Opens a relic chest in Korthia.\nRequires Tier 2 research level with The Archivists' Codex.\n\"The hand-scorched sigils along the side of the key may unlock the mysteries of relics within the Seeker's Quorum.\"\nSell Price:" }
entries[187615] = { ["name"] = "Orb Fragment", ["text"] = "Quest Item\n\"Covered in claw and teeth marks.\"" }
entries[187617] = { ["name"] = "Tempered Djaradin Steel", ["text"] = "Construction Material\nBinds when picked up\nDuration: 10 min\nCrafting Reagent\n\"Collected from djaradin armor and structures defeated in battle.\"\nSell Price:" }
entries[187618] = { ["name"] = "Site Oeth Circuit", ["text"] = "Quest Item\n\"Though its workings are unclear, this device is used by the Automa to gain entrance to Site Oeth.\"" }
entries[187619] = { ["name"] = "Winding Seed", ["text"] = "Quest Item\n\"Vines curl around the internals, moving and pulsing with life.\"" }
entries[187620] = { ["name"] = "Winding Seed", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires level 60 to 60 ( 60)\n\"Metal gears and living vines, fused together.\"" }
entries[187621] = { ["name"] = "Writ of Construction", ["text"] = "Construction Material\nBinds when picked up\n\"Authorizes the start of construction at various sites around the Dragon Isles.\"\nSell Price:" }
entries[187626] = { ["name"] = "Suspicious Papers", ["text"] = "Quest Item\nUnique (10)\nRequires level 60 to 60 ( 60)\n\"These scraps of paper have strange scribblings on them, almost certainly a code.\"" }
entries[187628] = { ["name"] = "Restoration Matrix", ["text"] = "Quest Item\nUnique\n\"An instrument of significant power for the automa. However, this device is severely depleted.\"\nSell Price:" }
entries[187629] = { ["name"] = "Heartlight Stone", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Heartlight Vombata mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires The Enlightened\n- Exalted\n\n\"The Enlightened revere all creations of the First Ones, yet for many, the vombata of Zereth Mortis are the most beloved. These creatures are equal parts trusted beast of burden and beloved companion.\"\nVendor:\nVilo\nZone:\nZereth Mortis\nFaction:\nThe Enlightened - Exalted\nCost:\n5000" }
entries[187630] = { ["name"] = "Curious Crystalsniffer", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Most vombata enjoy tunneling through the ground, but these sniffers seem to have an unerring ability to locate crystals buried deep underground and will congregate around large deposits.\"\nProfession:\nProtoform Synthesis" }
entries[187631] = { ["name"] = "Darkened Vombata", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The schematic to synthesize these darkened vombata seem to have appeared as a reaction to the Mawsworn invasion. The resulting vombata look different--darker, much like the invaders--but behave normally.\"\nProfession:\nProtoform Synthesis" }
entries[187632] = { ["name"] = "Adorned Vombata", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Red-colored vombata are considered lucky by the Enlightened. It was a red vombata that was present when they first arrived in Zereth Mortis.\"\nProfession:\nProtoform Synthesis" }
entries[187633] = { ["name"] = "Bufonid Lattice", ["text"] = "Protoform Synthesis\nCrafting Reagent\n\"A mystical lattice used to synthesize an bufonid.\"" }
entries[187634] = { ["name"] = "Ambystan Lattice", ["text"] = "Protoform Synthesis\nCrafting Reagent\n\"A mystical lattice used to synthesize an ambystan.\"" }
entries[187635] = { ["name"] = "Cervid Lattice", ["text"] = "Protoform Synthesis\nCrafting Reagent\n\"A mystical lattice used to synthesize a cervid.\"" }
entries[187636] = { ["name"] = "Aurelid Lattice", ["text"] = "Protoform Synthesis\nCrafting Reagent\n\"A mystical lattice used to synthesize an aurelid.\"" }
entries[187637] = { ["name"] = "Navarro's Backpack", ["text"] = "Binds when picked up\nUse: Grab your favorite backpack and go! (5 Sec Cooldown)" }
entries[187638] = { ["name"] = "Deathrunner", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These wild cervids are only truly at peace when running through--or between--the lands of Death.\"\nProfession:\nProtoform Synthesis" }
entries[187639] = { ["name"] = "Pale Regal Cervid", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Looking at these majestic creatures, it's not difficult to see how the idea of cervids developed into the stags found on Azeroth and other mortal worlds.\"\nProfession:\nProtoform Synthesis" }
entries[187640] = { ["name"] = "Anointed Protostag Reins", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon an Anointed Protostag mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires The Enlightened\n- Revered\n\n\"Only those most esteemed by the Enlightened are trusted with the reins of this rare cervid.\"\nVendor:\nVilo\nZone:\nZereth Mortis\nFaction:\nThe Enlightened - Revered\nCost:\n5000" }
entries[187641] = { ["name"] = "Reins of the Sundered Zerethsteed", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Whatever the purpose of these cervids once was, it is long forgotten. Though they are not Dominated, they have been corrupted by the unintended presence of Mawsworn in the sacred realm of Zereth Mortis.\"\nProfession:\nProtoform Synthesis" }
entries[187642] = { ["name"] = "Vicious Warstalker", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon a Vicious Warstalker.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Trample the Alliance to dust while riding a majestic protoform wolf! For the Horde!\"\nPvP:\nShadowlands: Season 4\nRated Arena and Rated Battleground Season Reward" }
entries[187644] = { ["name"] = "Vicious Warstalker", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon a Vicious Warstalker.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Trample the Horde to dust while riding a majestic protoform wolf! For the Alliance!\"\nPvP:\nShadowlands: Season 4\nRated Arena and Rated Battleground Season Reward" }
entries[187648] = { ["name"] = "Empty Kettle of Stone Soup", ["text"] = "Use: Set out a Kettle of Stone Soup, ready to fill with delicious ingredients. Finish it to provide 70 servings to your raid or party!\n\nOnce complete, restores 173077 health and 138461 mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 53 in a stat for 1 hour.\nSell Price:" }
entries[187650] = { ["name"] = "Staff of Draconic Energies", ["text"] = "Binds when picked up\nTwo-Hand Staff\n5 - 7 Damage Speed 3.60\n(1.7 damage per second)\n+20 Intellect\n+7 Stamina\n+ 3 Critical Strike\n+ 6 Haste\nClasses: Evoker\nSell Price:" }
