entries[187659] = { ["name"] = "Adventurer's Footlocker", ["text"] = "Binds when picked up\n\"Contains gear for other class specializations.\"\n<Right Click to Open>" }
entries[187660] = { ["name"] = "Vespoid Flutterer", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A flutterer is an overgrown vespoid worker created to carry a rider. Rather than looking to a queen for leadership, it looks to its rider to guide it in all things.\"\nProfession:\nProtoform Synthesis" }
entries[187662] = { ["name"] = "Strange Goop", ["text"] = "Unique\n\"The aurelids of Zereth Mortis seem attracted to this substance, but it resists attachment to any lure. Someone more familiar with deep sea creatures may know what to do with it.\"" }
entries[187663] = { ["name"] = "Bronzewing Vespoid", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Bronzewing vespoids are the result of attempting to synthesize a vespoid queen with no other members of a new hive. While no mortal has yet discovered how to synthesize a hive, the bronzewings are reliable mounts just as they are.\"\nProfession:\nProtoform Synthesis" }
entries[187664] = { ["name"] = "Forged Spiteflyer", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"There's nothing that can make you feel as alive quite like riding through the realm of Death while atop a being that hates you.\"\nProfession:\nProtoform Synthesis" }
entries[187665] = { ["name"] = "Buzz", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Buzz buzz buzz, buzz buzz! Buzz buzz buzz buzz buzz. Buzz buzz buzz, buzz buzz buzz.\"\nProfession:\nProtoform Synthesis" }
entries[187666] = { ["name"] = "Desertwing Hunter", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"In service of the great Purpose, desertwing hunters were designed to fill distant skies of forgotten realms of the Shadowlands.\"\nProfession:\nProtoform Synthesis" }
entries[187667] = { ["name"] = "Mawdapted Raptora", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Since the Jailer's incursion, new raptora have been synthesized by Zereth Mortis that are capable of resisting the corrupting influence of the Maw.\"\nProfession:\nProtoform Synthesis" }
entries[187668] = { ["name"] = "Raptora Swooper", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The raptora swooper is one of the most vicious iterations of its kind, perfectly suited for its ecological niche. Needing no further adjustments, the ones synthesized today are identical to those created in the past.\"\nProfession:\nProtoform Synthesis" }
entries[187669] = { ["name"] = "Serenade", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These beautiful helicids emerge only at night. When they are pleased, their shells hum with a joyful melody.\"\nProfession:\nProtoform Synthesis" }
entries[187670] = { ["name"] = "Bronze Helicid", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Some helicids of Zereth Mortis have strangely metallic shells. The ones who do are generally a bronze color, indistinct from the metal any novice miner could work, save that this creature's construction far surpasses the skill of any novice.\"\nProfession:\nProtoform Synthesis" }
entries[187671] = { ["name"] = "Unsuccessful Prototype Fleetpod", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This creature was not designed by the First Ones, but instead by an unknown being attempting to create a very fast runner. Needless to say the attempt failed, because this mount is very slow.\"\nProfession:\nProtoform Synthesis" }
entries[187672] = { ["name"] = "Scarlet Helicid", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This helicid's unusual reddish tint is clearly intentional in its design, but the only other difference between these and other helicids is the unusual lack of any ooze.\"\nProfession:\nProtoform Synthesis" }
entries[187673] = { ["name"] = "Cryptic Aurelid", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The Cyphers of the First Ones are beyond any mortal understanding. A curious effect of the language is that, for reasons unknown, some aurelids are drawn to mortals who aspire to unlock its mystery.\"\nAchievement:\nFrom A to Zereth\nCategory:\nShadowlands" }
entries[187674] = { ["name"] = "Depthstalker", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Depthstalker.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Poached from Zereth Mortis, a few of these jellyfish were lost when the poachers' ship sank. They found a new home in the Great Sea's depths.\"\nTrading Post" }
entries[187675] = { ["name"] = "Shimmering Aurelid", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Though it was once created to defend the Sepulcher of the First Ones, with its primary function now completed, it now obediently follows your command.\"\nAchievement:\nGlory of the Sepulcher Raider\nCategory:\nDungeons & Raids" }
entries[187676] = { ["name"] = "Deepstar Polyp", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Deepstar Aurelid.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"As one of the last remaining polyps of an elusive creature, this aurelid is at home in the water as much as the air.\"\nDrop:\nHirukon\nZone:\nZereth Mortis" }
entries[187677] = { ["name"] = "Genesis Crawler", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The Enlightened who have observed tarachnids believe that this variety may be some of the first beings to ever walk the land of Zereth Mortis.\"\nProfession:\nProtoform Synthesis" }
entries[187678] = { ["name"] = "Tarachnid Creeper", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These tarachnids make their home in the darkest corners of Zereth Mortis, coming out only to hunt (or, sometimes, carry a rider around).\"\nProfession:\nProtoform Synthesis" }
entries[187679] = { ["name"] = "Ineffable Skitterer", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These tarachnids move with a purpose unknown to others, answering only to a higher calling. Whatever that may be, it appears to include routine assistance to mortals who need a ride. For now.\"\nProfession:\nProtoform Synthesis" }
entries[187680] = { ["name"] = "Vicious War Croaker", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon a Vicious War Croaker.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"These creatures are so enthusiastic when charging into battle that they will croak out something that sounds very much like \"FOR THE HORDE!\"\"\nPvP:\nShadowlands: Season 3\nRated Arena and Rated Battleground Season Reward" }
entries[187681] = { ["name"] = "Vicious War Croaker", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon a Vicious War Croaker.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"These creatures are so enthusiastic when charging into battle that they will croak out something that sounds very much like \"FOR THE ALLIANCE!\"\"\nPvP:\nShadowlands: Season 3\nRated Arena and Rated Battleground Season Reward" }
entries[187682] = { ["name"] = "Wastewarped Deathwalker", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Raw swirling energy bound together into a cohesive form, it will only bend to the will of those strong enough to bind it.\"\nAchievement:\nShadowlands Keystone Master: Season Three\nCategory:\nDungeons" }
entries[187683] = { ["name"] = "Goldplate Bufonid", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This armored bufonid is always ready to leap into battle... as long as that battle is really, really close. In a pinch, it can leap multiple times and eventually reach the battle.\"\nProfession:\nProtoform Synthesis" }
entries[187684] = { ["name"] = "Containment Trap", ["text"] = "Quest Item\nUse: Traps target in a containment field to allow further examination. (15 Sec Cooldown)\n\"Keeps researchers safe and unharmed.\"" }
