entries[187700] = { ["name"] = "Progenium Ore", ["text"] = "Crafting Reagent\n\"Can be mined from deposits and elementals found in the most rugged and dangerous areas of Zereth Mortis.\"\nSell Price:" }
entries[187701] = { ["name"] = "Protogenic Pelt", ["text"] = "Crafting Reagent\n\"Players with the skinning skill can gather these rare hides from the strongest creatures inhabiting Zereth Mortis.\"\nSell Price:" }
